<template><div class="page"><el-card><template #header>账号封禁</template><el-form :model="form" label-width="100px" style="max-width:520px"><el-form-item label="用户Woha ID"><el-input v-model.number="form.chatNo"/></el-form-item><el-form-item label="封禁天数"><el-input-number v-model="form.dayNum" :min="1" :max="7"/></el-form-item><el-form-item label="封禁原因"><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="200" show-word-limit/></el-form-item><el-button type="danger" @click="ban">执行封禁</el-button><el-button @click="release">提前解封</el-button></el-form></el-card></div></template>
<script setup>import { ElMessage, ElMessageBox } from 'element-plus'; import { banExternalAccount, releaseExternalAccountBan } from '@/api/external/manager'; const form=reactive({chatNo:undefined,dayNum:1,reason:''}); async function ban(){if(!form.chatNo||!form.reason)return ElMessage.warning('请填写用户Woha ID和封禁原因');await ElMessageBox.confirm(`确认封禁账号 ${form.chatNo} ${form.dayNum} 天？`,'提示',{type:'warning'});await banExternalAccount(form);ElMessage.success('封禁成功')} async function release(){if(!form.chatNo)return ElMessage.warning('请输入用户Woha ID');await ElMessageBox.confirm(`确认解除账号 ${form.chatNo} 的封禁？`,'提示',{type:'warning'});await releaseExternalAccountBan(form.chatNo);ElMessage.success('已解除封禁')}</script><style scoped>.page{padding:20px}</style>
